#!/usr/bin/env bash
# A2.1 — ratchet baseline expiry gate (issue #91).
#
# eslint-suppressions.json (generated by `eslint --suppress-rule`, ESLint
# 10's native Suppressions feature — see `eslint --help` "Suppressing
# Violations") is the ratchet itself: it lets pre-existing findings for a
# newly-enabled rule through while still failing the build on any NEW
# violation. That mechanism has no expiry of its own — a baseline, once
# written, would sit forever with no forcing function to revisit it. This
# script is that forcing function: every rule that appears anywhere in
# eslint-suppressions.json must have a corresponding, unexpired entry in
# eslint-suppressions.expiry.json. A missing entry and a past expiry date
# both fail the build — loud, not silent (issue #91 / A2.1 acceptance:
# "baselines expire on explicit date, not silently").
#
# To renew: bump "expires" in eslint-suppressions.expiry.json in a reviewed
# PR that states why (still burning down / deliberately re-scoped).
# To retire a rule once its findings are at zero:
#   pnpm run lint -- --suppress-rule <rule-id> --prune-suppressions
# then delete that rule's entry from eslint-suppressions.expiry.json once
# eslint-suppressions.json no longer mentions it.
#
# Usage: bash scripts/check-eslint-suppression-expiry.sh
# Exit 0 = every baselined rule has a live (non-expired) expiry entry.
# Exit 1 = a rule is baselined with no expiry entry, or its baseline expired.
set -euo pipefail

SUPPRESSIONS="eslint-suppressions.json"
EXPIRY="eslint-suppressions.expiry.json"

if [[ ! -f "$SUPPRESSIONS" ]]; then
  echo "eslint-suppression-expiry: no $SUPPRESSIONS — nothing baselined, clean."
  exit 0
fi

if [[ ! -f "$EXPIRY" ]]; then
  echo "eslint-suppression-expiry: $SUPPRESSIONS exists but $EXPIRY is missing."
  echo "eslint-suppression-expiry: EXPIRED — every baselined rule needs a recorded expiry date."
  exit 1
fi

mapfile -t RULES < <(jq -r '[.[] | keys[]] | unique[]' "$SUPPRESSIONS" | tr -d '\r')

today=$(date -u +%F)
violations=0

for rule in "${RULES[@]}"; do
  # A Windows-native jq on stdout can line-end with CRLF, which would
  # otherwise leave a trailing \r baked into $rule/$expires and make every
  # lookup below miss. Strip defensively so this script behaves the same on
  # a contributor's machine and in CI (ubuntu-latest, LF-only jq).
  expires=$(jq -r --arg r "$rule" '.[$r].expires // empty' "$EXPIRY" | tr -d '\r')
  if [[ -z "$expires" ]]; then
    echo "eslint-suppression-expiry: EXPIRED — rule '$rule' has baselined violations in $SUPPRESSIONS but no entry in $EXPIRY."
    violations=$((violations + 1))
    continue
  fi
  # Fail closed on malformed expiry values instead of comparing them as
  # strings. A lexicographic compare treats any value that merely SORTS
  # after today (e.g. "9999-99-99", or an unpadded "2026-8-01" which sorts
  # before an actual same-day value) as "not yet expired" without it being a
  # real date at all — a permanent-suppression bypass anyone could type. Both
  # gates below are required: the regex pins the exact zero-padded
  # YYYY-MM-DD shape (GNU date -d alone still parses "2026-8-01"), and
  # `date -d` rejects shapes that match the regex but aren't real calendar
  # dates (e.g. "2026-02-30", "2026-13-01") without silently rolling them
  # over to a neighboring date.
  if [[ ! "$expires" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
    echo "eslint-suppression-expiry: EXPIRED — rule '$rule' has a malformed expiry '$expires' in $EXPIRY (must be exact zero-padded YYYY-MM-DD)."
    violations=$((violations + 1))
    continue
  fi
  if ! date -u -d "$expires" +%F >/dev/null 2>&1; then
    echo "eslint-suppression-expiry: EXPIRED — rule '$rule' has an invalid calendar date '$expires' in $EXPIRY."
    violations=$((violations + 1))
    continue
  fi
  if [[ "$expires" < "$today" ]]; then
    echo "eslint-suppression-expiry: EXPIRED — rule '$rule' baseline expired on $expires (today: $today). Burn it down or renew the date with a reviewed edit to $EXPIRY."
    violations=$((violations + 1))
  fi
done

if (( violations > 0 )); then
  echo "eslint-suppression-expiry: $violations rule(s) failed — see EXPIRED lines above"
  exit 1
fi

echo "eslint-suppression-expiry: clean (${#RULES[@]} baselined rule(s) in $SUPPRESSIONS, all unexpired)"
